/*
 * A191123  Increasing sequence generated by these rules: a(1)=1, and if x is
 *          in a then 3x-1 and 4x+1 are in a.
 * https://oeis.org/A191123
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   not stated
 * Range:     u8 n <= 12, u16 n <= 519, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   seq_alloc, seq_realloc
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence A191123:  a(1)=1; if x is in a, then 3x-1 and 4x+1 are in a.
 * This implementation uses a priority queue (min‑heap) to generate terms
 * in increasing order, and a sorted array to deduplicate future candidates.
 * The first n terms are cached in a static array so that the function
 * works correctly for any order of calls.
 */
#include "../utils/seq_alloc.h"
#include "../utils/seq_realloc.h"
#include <stddef.h>   /* for size_t */

/* --------------------------------------------------------------------- */
/*  Static data structures                                               */
/* --------------------------------------------------------------------- */
static seq_t *cache  = NULL; /* array of generated values                */
static size_t cache_len = 0, cache_cap = 0;

static seq_t *seen   = NULL; /* sorted list of all frontier values      */
static size_t seen_len  = 0, seen_cap  = 0;

static seq_t *heap   = NULL; /* min‑heap of frontier values             */
static size_t heap_len  = 0, heap_cap  = 0;

/* --------------------------------------------------------------------- */
/*  Utility helpers                                                      */
/* --------------------------------------------------------------------- */

/* binary search: returns the first index where val could be inserted */
/* (i.e. the lower bound).  The array is strictly increasing.          */
static size_t binary_search_seen(seq_t val)
{
    size_t lo = 0, hi = seen_len;
    while (lo < hi) {
        size_t mid = (lo + hi) >> 1;
        if (seen[mid] < val)
            lo = mid + 1;
        else
            hi = mid;
    }
    return lo;
}

/* true if val is already present in 'seen' */
static int seen_contains(seq_t val)
{
    size_t pos = binary_search_seen(val);
    return (pos < seen_len && seen[pos] == val);
}

/* Insert val into 'seen', keeping the array sorted.  No duplicate
 * insertion is performed.                                                       */
static void insert_seen(seq_t val)
{
    size_t pos = binary_search_seen(val);
    if (pos < seen_len && seen[pos] == val)   /* already stored */
        return;

    /* Grow array if necessary */
    if (seen_len == seen_cap) {
        size_t newcap = (seen_cap == 0) ? 8 : seen_cap * 2;
        seq_t *tmp = seq_realloc(seen, seen_cap, newcap);
        seen = tmp;
        seen_cap = newcap;
    }

    /* Shift elements to open space for the new value */
    for (size_t i = seen_len; i > pos; --i)
        seen[i] = seen[i - 1];
    seen[pos] = val;
    ++seen_len;
}

/* --------------------------------------------------------------------- */
/*  Min‑heap operations                                                 */
/* --------------------------------------------------------------------- */

/* Push a new value onto the heap, maintaining the min‑heap property.   */
static void heap_push(seq_t val)
{
    if (heap_len == heap_cap) {
        size_t newcap = (heap_cap == 0) ? 8 : heap_cap * 2;
        seq_t *tmp = seq_realloc(heap, heap_cap, newcap);
        heap = tmp;
        heap_cap = newcap;
    }
    heap[heap_len++] = val;
    size_t i = heap_len - 1;
    while (i > 0) {
        size_t parent = (i - 1) >> 1;
        if (heap[parent] <= heap[i])
            break;
        seq_t tmp = heap[parent];
        heap[parent] = heap[i];
        heap[i] = tmp;
        i = parent;
    }
}

/* Pop (remove) the smallest element from the heap.                     */
static seq_t heap_pop(void)
{
    seq_t root = heap[0];
    heap[0] = heap[--heap_len];

    size_t i = 0;
    while (1) {
        size_t left = (i << 1) + 1;
        if (left >= heap_len)
            break;
        size_t right = left + 1;
        size_t child = (right < heap_len && heap[right] < heap[left]) ? right : left;
        if (heap[i] <= heap[child])
            break;
        seq_t tmp = heap[i];
        heap[i] = heap[child];
        heap[child] = tmp;
        i = child;
    }
    return root;
}

/* --------------------------------------------------------------------- */
/*  Public sequence function                                            */
/* --------------------------------------------------------------------- */
seq_t a(idx_t n)
{
    /* n is guaranteed to be >= 1; convert once for array indexing */
    size_t target = (size_t)n;

    /* ---------- Initialization on first call ---------- */
    if (cache_len == 0) {
        /* Allocate initial storage */
        cache = seq_alloc(8);
        cache_cap = 8;

        seen = seq_alloc(8);
        seen_cap = 8;

        heap = seq_alloc(8);
        heap_cap = 8;

        /* Seed the sequence with the starting element 1 */
        seq_t one = (seq_t)1;
        insert_seen(one);
        heap_push(one);
    }

    /* ---------- Generate terms until we have enough ---------- */
    while (cache_len < target) {
        seq_t cur = heap_pop();  /* smallest frontier value */

        /* Store in cache */
        if (cache_len == cache_cap) {
            size_t newcap = cache_cap * 2;
            seq_t *tmp = seq_realloc(cache, cache_cap, newcap);
            cache = tmp;
            cache_cap = newcap;
        }
        cache[cache_len++] = cur;

        /* Generate the two successors */
        seq_t nxt1 = cur * (seq_t)3 - (seq_t)1;   /* 3x - 1 */
        seq_t nxt2 = cur * (seq_t)4 + (seq_t)1;   /* 4x + 1 */

        /* Insert successors if unseen */
        if (!seen_contains(nxt1)) {
            insert_seen(nxt1);
            heap_push(nxt1);
        }
        if (!seen_contains(nxt2)) {
            insert_seen(nxt2);
            heap_push(nxt2);
        }
    }

    return cache[target - 1];
}
